import{_ as n,C as l,o,c as a,ag as s,E as t}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Seller Management","description":"","frontmatter":{},"headers":[],"relativePath":"sellers/seller-management.md","filePath":"sellers/seller-management.md","lastUpdated":1786111645000}'),i={name:"sellers/seller-management.md"};function g(d,e,p,h,m,c){const r=l("ImagePopup");return o(),a("div",null,[e[0]||(e[0]=s('<h1 id="seller-management" tabindex="-1">Seller Management <a class="header-anchor" href="#seller-management" aria-label="Permalink to &quot;Seller Management&quot;">​</a></h1><p>Seller Management is the admin&#39;s control centre for the people who sell on the marketplace — onboarding them, setting what they can do, approving their accounts and products, and stepping in when needed. It all lives under <strong>Marketplace → Sellers</strong> in the admin panel.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How sellers register, and the settings that govern it</li><li>What the admin sellers list shows and the actions on it</li><li>How to create, edit, approve, and remove a seller</li></ul></div><h2 id="how-sellers-register" tabindex="-1">How sellers register <a class="header-anchor" href="#how-sellers-register" aria-label="Permalink to &quot;How sellers register&quot;">​</a></h2><p>Sellers sign up from the storefront (or the admin creates them). A few admin settings under <strong>Configure → Marketplace</strong> shape registration:</p><ul><li><strong>Registration &amp; Visibility</strong> — whether new sellers need <strong>approval</strong>, whether seller profiles <strong>show publicly</strong> on the storefront, and whether sellers <strong>can view customers</strong>.</li><li><strong>Order Capabilities</strong> — what sellers may do with orders: <strong>create invoice</strong>, <strong>create shipment</strong>, <strong>cancel order</strong>, and whether a <strong>minimum order amount</strong> applies.</li><li><strong>Uploads</strong> — the <strong>maximum file size</strong> sellers can upload (used for logos, banners, and bulk-upload image ZIPs).</li></ul><p>Exactly which fields a seller fills in at sign-up is driven by the <a href="/sellers/seller-attributes">Seller Attributes</a> marked &quot;visible on sign up&quot;.</p><h2 id="the-sellers-list" tabindex="-1">The sellers list <a class="header-anchor" href="#the-sellers-list" aria-label="Permalink to &quot;The sellers list&quot;">​</a></h2><p>Open <strong>Marketplace → Sellers</strong>. Each row is a top-level seller, with columns for <strong>Seller Name</strong>, <strong>Email</strong>, <strong>Slug</strong>, <strong>Cancellation Rate</strong>, <strong>Average Rating</strong>, <strong>Flags</strong>, <strong>Account Health</strong> (a colour-coded score with a Healthy / At Risk / Unhealthy filter), <strong>Status</strong> (Approved / Disapproved), <strong>Suspended</strong>, and <strong>Created At</strong>.</p>',9)),t(r,{src:"/images/seller-management/admin-sellers-grid.png",alt:"Admin sellers list"}),e[1]||(e[1]=s('<p>Per-row actions include <strong>Edit</strong>, <strong>Delete</strong>, <strong>Login as Seller</strong> (impersonate), and <strong>Refresh Account Health</strong>. Bulk actions let you <strong>Update Status</strong> (Approve / Disapprove), <strong>Refresh Account Health</strong>, or <strong>Delete</strong> across a selection.</p><h2 id="creating-a-seller" tabindex="-1">Creating a seller <a class="header-anchor" href="#creating-a-seller" aria-label="Permalink to &quot;Creating a seller&quot;">​</a></h2><p>Use <strong>Create</strong> (a modal on the list) to onboard a seller manually — <strong>name</strong>, <strong>email</strong>, <strong>phone</strong>, <strong>slug</strong>, and a <strong>password</strong>. Whether the new seller is auto-approved depends on your <strong>Approval Required</strong> setting.</p><h2 id="editing-a-seller" tabindex="-1">Editing a seller <a class="header-anchor" href="#editing-a-seller" aria-label="Permalink to &quot;Editing a seller&quot;">​</a></h2><p>The seller edit form is built from <a href="/sellers/seller-attributes">Seller Attributes</a>, grouped into cards, with a channel/locale switcher for per-channel and per-language values.</p>',5)),t(r,{src:"/images/seller-management/admin-seller-edit.png",alt:"Admin seller edit form"}),e[2]||(e[2]=s('<p>The default groups are:</p><ul><li><strong>General</strong> — name, email, phone, slug, business name.</li><li><strong>Description</strong> and <strong>Policies</strong> — business description, plus return / shipping / privacy policies.</li><li><strong>Meta Description</strong> — SEO title, keywords, description.</li><li><strong>Address</strong> and <strong>Social Links</strong>.</li><li><strong>Settings</strong> — the seller&#39;s <strong>Suspended</strong> toggle, <strong>Commission Enabled</strong> + <strong>Commission Percentage</strong> (a per-seller override of the global rate — see <a href="/payments/commission-management">Commission Management</a>), <strong>Minimum Order Amount</strong>, <strong>Google Analytics ID</strong>, <strong>Allowed Product Types</strong>, and <strong>Magic AI</strong> enablement + generation limit.</li></ul><p>The right side shows read-only <strong>Total Sales</strong>, <strong>Commission</strong>, and <strong>Seller Earnings</strong> summaries, plus the seller&#39;s sub-users, channels, and categories.</p><h2 id="approving-impersonating-and-removing" tabindex="-1">Approving, impersonating, and removing <a class="header-anchor" href="#approving-impersonating-and-removing" aria-label="Permalink to &quot;Approving, impersonating, and removing&quot;">​</a></h2><ul><li><strong>Approve / Disapprove</strong> — via the bulk <strong>Update Status</strong> action (select one or more sellers); the seller is emailed when their status changes. A disapproved seller can&#39;t sell.</li><li><strong>Login as Seller</strong> — open the Seller Panel as that seller to see exactly what they see (great for support).</li><li><strong>Delete</strong> — remove a seller. This is <strong>blocked</strong> if the seller still has <strong>pending or processing orders</strong>, so no in-flight order is orphaned.</li><li><strong>Flags</strong> — review the flags customers have raised against a seller. See <a href="/moderation/seller-product-flagging">Seller &amp; Product Flagging</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep an eye on the <strong>Account Health</strong> column — it surfaces struggling sellers (high cancellations, low ratings, or flags) at a glance. See <a href="/sellers/seller-account-health">Seller Account Health</a>.</p></div>',6))])}const v=n(i,[["render",g]]);export{f as __pageData,v as default};
